constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
  super(element, config)

  this._calendar = null
  this._isShown = false

  this._initCalendar()

  // Remove aria-haspopup to prevent Tab key blocking
  if (this._isInput) {
    this._element.removeAttribute('aria-haspopup')
  }
}

edits.before:
  this._setupDismiss()

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.after:
  this._setupDismiss()

  // Allow Tab key to move focus out of the input when the calendar is not shown
  if (this._isInput && !this._isInline) {
    this._element.addEventListener('keydown', (event: KeyboardEvent) => {
      if (event.key === 'Tab' && !this._isShown) {
        event.stopImmediatePropagation()
      }
    }, true)
  }

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}
